import{_ as e,a as o,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Export Bookings","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-bookings-export","title":"Export Bookings (CSV)","description":"Download the bookings datagrid as a CSV file — the same data the admin Bookings \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/bookings/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output bookings.csv\\n","response":"# Binary response: a text/csv attachment is written to bookings.csv\\n# (Content-Disposition: attachment; filename=\\"bookings.csv\\"). Sample contents:\\n\\nID,\\"Order ID\\",Qty,From,To,\\"Booking Date\\"\\n17,2391,1,\\"20 May, 2026 13:00PM\\",\\"20 May, 2026 14:00PM\\",\\"2026-05-19 13:11:39\\"\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/bookings/export.md","filePath":"api/rest-api/admin/sales/bookings/export.md","lastUpdated":1783079210000}'),d={name:"api/rest-api/admin/sales/bookings/export.md"};function s(n,t,i,c,p,h){return a(),o("div",null,t[0]||(t[0]=[r('<h1 id="export-bookings" tabindex="-1">Export Bookings <a class="header-anchor" href="#export-bookings" aria-label="Permalink to &quot;Export Bookings&quot;">​</a></h1><p>Downloads the bookings datagrid as a <strong>CSV file</strong> — the same data the admin <strong>Sales → Bookings</strong> &quot;Export&quot; button produces. The response is a binary <code>text/csv</code> attachment, not JSON. Requires the <code>sales.bookings.view</code> permission.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/bookings/export</code></td><td>GET</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The CSV carries the six datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Booking id.</td></tr><tr><td><code>Order ID</code></td><td>The parent order&#39;s number.</td></tr><tr><td><code>Qty</code></td><td>Quantity booked.</td></tr><tr><td><code>From</code></td><td>The slot&#39;s start, formatted (empty for non-time-based booking types).</td></tr><tr><td><code>To</code></td><td>The slot&#39;s end, formatted (empty for non-time-based booking types).</td></tr><tr><td><code>Booking Date</code></td><td>When the booking was created.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><p><code>format</code> selects the export format — <strong>only <code>csv</code> is supported</strong> (the default); any other value returns <code>422</code>.</p><p>The export honours the <strong>same filters as the <a href="/api/rest-api/admin/sales/bookings/list.html">listing</a></strong>, so you export exactly the rows you&#39;re viewing: <code>id</code>, <code>order_id</code>, <code>qty</code>, <code>product_id</code>, <code>from_from</code> / <code>from_to</code>, <code>to_from</code> / <code>to_to</code>, <code>created_at_from</code> / <code>_to</code>. (Pagination does not apply — the export returns every matching row.)</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.bookings.view</code></p>',12)]))}const u=e(d,[["render",s]]);export{m as __pageData,u as default};
